import{installCloudLabTheme}from"./chunk-AI2WMLLJ.js";var CLOUD_DEMOS=new Map([["flat","Flat clouds"],["planet","Planet clouds"],["fluid","Fluid clouds"]]);var normalizeDemo=demo=>CLOUD_DEMOS.has(demo)?demo:"flat";function selectedCloudDemo(url=window.location.href){const demo=new URL(url).searchParams.get("demo");return normalizeDemo(demo)}function cloudDemoUrl(demo,url=window.location.href){const target=new URL(url);target.searchParams.set("demo",normalizeDemo(demo));return target.href}var mountedRoute;var cloudRoute=href=>{const{pathname,search}=new URL(href);return pathname+search};function watchCloudDemoHistory(){mountedRoute=cloudRoute(window.location.href);window.addEventListener("popstate",()=>{if(cloudRoute(window.location.href)!==mountedRoute)window.location.reload()})}function pushCloudDemoRoute(url){window.history.pushState(null,"",url);mountedRoute=cloudRoute(window.location.href)}function populateCloudDemoNavigation(nav,doc=document,url=window.location.href){nav.setAttribute("aria-label","Cloud demos");const current=selectedCloudDemo(url);for(const[demo,label]of CLOUD_DEMOS){const link=doc.createElement("a");link.textContent=label;link.href=cloudDemoUrl(demo,url);if(demo===current){link.setAttribute("aria-current","page");link.addEventListener("click",event=>event.preventDefault())}nav.appendChild(link)}return nav}function mountCloudDemoNavigation(doc=document,url=window.location.href){installCloudLabTheme(doc);const existing=doc.getElementById("cloud-demo-navigation");if(existing)return existing;const nav=doc.createElement("nav");nav.id="cloud-demo-navigation";nav.className="cl-switch cl-switch--floating";populateCloudDemoNavigation(nav,doc,url);doc.body.appendChild(nav);return nav}export{selectedCloudDemo,cloudDemoUrl,watchCloudDemoHistory,pushCloudDemoRoute,populateCloudDemoNavigation,mountCloudDemoNavigation};
